import java.util.*;

public class Main {
    int[][] generateMatrix(int n) {
        int[][] matrix = new int[n][n];              // the answer grid, starts empty
        boolean[][] visited = new boolean[n][n];       // separate grid tracking where we've already been
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}}; // right, down, left, up
        int row = 0, col = 0, dirIndex = 0;
        for (int num = 1; num <= n * n; num++) {
            matrix[row][col] = num;                     // fill the current cell with the next number
            visited[row][col] = true;                    // mark this cell as visited
            int nextRow = row + directions[dirIndex][0];
            int nextCol = col + directions[dirIndex][1];
            // turn clockwise if the next cell is out of bounds or already visited
            if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n || visited[nextRow][nextCol]) {
                dirIndex = (dirIndex + 1) % 4;
            }
            row += directions[dirIndex][0];
            col += directions[dirIndex][1];
        }
        return matrix;
    }

    public static void main(String[] args) {
        int n = 3;
        Main solution = new Main();
        for (int[] row : solution.generateMatrix(n)) {
            System.out.println(Arrays.toString(row));
        }
    }
}

