def generate_matrix(n):
    matrix = [[0] * n for _ in range(n)]   # the answer grid, starts empty
    top, bottom, left, right = 0, n - 1, 0, n - 1  # the four edges of the region left to fill
    num = 1
    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            matrix[top][col] = num          # fill across the top row
            num += 1
        top += 1                             # that row is done, shrink the top boundary
        for row in range(top, bottom + 1):
            matrix[row][right] = num        # fill down the right column
            num += 1
        right -= 1                           # shrink the right boundary
        if top <= bottom:
            for col in range(right, left - 1, -1):
                matrix[bottom][col] = num   # fill across the bottom row, right to left
                num += 1
            bottom -= 1                       # shrink the bottom boundary
        if left <= right:
            for row in range(bottom, top - 1, -1):
                matrix[row][left] = num     # fill up the left column, bottom to top
                num += 1
            left += 1                         # shrink the left boundary
    return matrix


if __name__ == "__main__":
    n = 3
    for row in generate_matrix(n):
        print(row)

