import java.util.*;

public class Main {
    int[][] generateMatrix(int n) {
        int[][] matrix = new int[n][n];                   // the answer grid, starts empty
        int top = 0, bottom = n - 1, left = 0, right = n - 1; // the four edges of the region left to fill
        int num = 1;
        while (top <= bottom && left <= right) {
            for (int col = left; col <= right; col++) {
                matrix[top][col] = num++;                    // fill across the top row
            }
            top++;                                            // that row is done, shrink the top boundary
            for (int row = top; row <= bottom; row++) {
                matrix[row][right] = num++;                   // fill down the right column
            }
            right--;                                          // shrink the right boundary
            if (top <= bottom) {
                for (int col = right; col >= left; col--) {
                    matrix[bottom][col] = num++;                // fill across the bottom row, right to left
                }
                bottom--;                                       // shrink the bottom boundary
            }
            if (left <= right) {
                for (int row = bottom; row >= top; row--) {
                    matrix[row][left] = num++;                  // fill up the left column, bottom to top
                }
                left++;                                         // shrink the left boundary
            }
        }
        return matrix;
    }

    public static void main(String[] args) {
        int n = 3;
        Main solution = new Main();
        for (int[] row : solution.generateMatrix(n)) {
            System.out.println(Arrays.toString(row));
        }
    }
}

